import java.io.*;
import java.util.Arrays;

public class CF939F {
    public static final int INF = (int) 1e8;
    public static BlockReader input;
    public static PrintStream output;

    public static void main(String[] args) throws FileNotFoundException {
        if (System.getProperty("ONLINE_JUDGE") == null) {
            input = new BlockReader(new FileInputStream("D:\\DataBase\\TESTCASE\\codeforces\\CF939F.in"));
            output = System.out;
        } else {
            input = new BlockReader(System.in);
            output = new PrintStream(new BufferedOutputStream(System.out), false);
        }

        solve();

        output.flush();
    }

    public static void solve() {
        int n = input.nextInteger();
        int k = input.nextInteger();

        int[][] intervals = new int[k + 2][2];
        for (int i = 1; i <= k; i++) {
            intervals[i][0] = input.nextInteger();
            intervals[i][1] = input.nextInteger();
        }
        intervals[k + 1][0] = 2 * n;
        intervals[k + 1][1] = 2 * n;

        k++;

        int[] dp = new int[n + 1];
        int[] lastDp = new int[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int i = 1; i <= k; i++) {
            int[] interval = intervals[i];
            int intervalLength = interval[1] - interval[0];
            int middleLength = interval[0] - intervals[i - 1][1];

            // Copy lastDp to dp with shift and INF fill
            System.arraycopy(lastDp, 0, dp, Math.min(dp.length, intervalLength + middleLength), Math.max(0, n + 1 - (intervalLength + middleLength)));
            Arrays.fill(dp, 0, Math.min(dp.length, intervalLength + middleLength), INF);

            // Flip once
            int minX = interval[1] - middleLength - intervalLength;
            int maxX = interval[1] - middleLength;
            for (int j = 0; j <= n; j++) {
                int minNeedTime = INF;
                int left = minX - j;
                int right = maxX - j;
                if (left < 0) left = 0;
                if (right > n) right = n;
                for (int t = left; t <= right; t++) {
                    if (lastDp[t] < minNeedTime) minNeedTime = lastDp[t];
                }
                dp[j] = Math.min(dp[j], minNeedTime + 1);
            }

            // Flip twice
            for (int j = 0; j <= n; j++) {
                int minNeedTime = INF;
                int left = j - middleLength - intervalLength;
                int right = j - middleLength;
                if (left < 0) left = 0;
                if (right > n) right = n;
                for (int t = left; t <= right; t++) {
                    if (lastDp[t] < minNeedTime) minNeedTime = lastDp[t];
                }
                dp[j] = Math.min(dp[j], minNeedTime + 2);
            }

            // Swap dp and lastDp for next iteration
            int[] temp = lastDp;
            lastDp = dp;
            dp = temp;
        }

        int minFlipTime = INF;
        for (int t = 0; t <= n; t++) {
            if (lastDp[t] < minFlipTime) minFlipTime = lastDp[t];
        }

        if (minFlipTime < INF) {
            output.println("Full");
            output.println(minFlipTime);
        } else {
            output.println("Hungry");
        }
    }

    public static class BlockReader {
        static final int EOF = -1;
        InputStream is;
        byte[] dBuf;
        int dPos, dSize, next;
        StringBuilder builder = new StringBuilder();

        public BlockReader(InputStream is) {
            this(is, 4096);
        }

        public BlockReader(InputStream is, int bufSize) {
            this.is = is;
            dBuf = new byte[bufSize];
            next = nextByte();
        }

        public int nextByte() {
            while (dPos >= dSize) {
                if (dSize == -1) {
                    return EOF;
                }
                dPos = 0;
                try {
                    dSize = is.read(dBuf);
                } catch (Exception e) {
                }
            }
            return dBuf[dPos++];
        }

        public String nextBlock() {
            builder.setLength(0);
            skipBlank();
            while (next != EOF && !Character.isWhitespace(next)) {
                builder.append((char) next);
                next = nextByte();
            }
            return builder.toString();
        }

        public void skipBlank() {
            while (Character.isWhitespace(next)) {
                next = nextByte();
            }
        }

        public int nextInteger() {
            skipBlank();
            int ret = 0;
            boolean rev = false;
            if (next == '+' || next == '-') {
                rev = next == '-';
                next = nextByte();
            }
            while (next >= '0' && next <= '9') {
                ret = (ret << 3) + (ret << 1) + next - '0';
                next = nextByte();
            }
            return rev ? -ret : ret;
        }

        public int nextBlock(char[] data, int offset) {
            skipBlank();
            int index = offset;
            int bound = data.length;
            while (next != EOF && index < bound && !Character.isWhitespace(next)) {
                data[index++] = (char) next;
                next = nextByte();
            }
            return index - offset;
        }

        public boolean hasMore() {
            skipBlank();
            return next != EOF;
        }
    }
}
